Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='oneowner', at=datetime(2026, 11, 2, 0, 0, 0), actor='owner', title='Each fact has one owner; repeated bugs in one area mean copies to delete, not more patches', body='When bugs keep recurring in one area, stop patching it. Audit it against one principle, one owner per fact: list every place that holds or derives the same fact, choose the one that owns it, and plan stages that delete the other copies. The one-owner plan (docs/ONEOWNER-PLAN-2026-11-02.md) applies this to the replicas: the core owns them, every other holder reads the core.', rationale='The owner, 2026-11-02: when such bugs keep happening it is a sign of spaghetti code, and simplifying principles fix things.', supersedes=()))